    "Uzak erişim adresi": "dirección de acceso remoto", // EN: Remote access address
    "Siparişlerim": "Mis pedidos", // EN: My Orders
    "Ödeme geçmişi (Siparişlerim)": "Historial de pagos (Mis pedidos)", // EN: Payment history (My Orders)
